```js
class Graph {
  constructor() {
    this.adjList = {};
  }

  addVertex(vertex) {
    if (!this.adjList[vertex]) this.adjList[vertex] = [];
  }

  addEdge(v1, v2) {
    this.adjList[v1].push(v2);
    this.adjList[v2].push(v1); // Undirected
  }
}
```

```js
function dfsRecursive(graph, start, visited = new Set()) {
  console.log(start);
  visited.add(start);
  for (let neighbor of graph[start]) {
    if (!visited.has(neighbor)) {
      dfsRecursive(graph, neighbor, visited);
    }
  }
}
```

```js
function dfsIterative(graph, start) {
  let stack = [start];
  let visited = new Set();

  while (stack.length) {
    let vertex = stack.pop();
    if (!visited.has(vertex)) {
      console.log(vertex);
      visited.add(vertex);
      for (let neighbor of graph[vertex]) {
        stack.push(neighbor);
      }
    }
  }
}
```

```js
function bfs(graph, start) {
  let queue = [start];
  let visited = new Set([start]);

  while (queue.length) {
    let vertex = queue.shift();
    console.log(vertex);
    for (let neighbor of graph[vertex]) {
      if (!visited.has(neighbor)) {
        visited.add(neighbor);
        queue.push(neighbor);
      }
    }
  }
}
```

To detect cycles in an undirected graph:
- Use DFS and track parent of each node.
- If a visited node is encountered that’s not the parent, there is a cycle.

```js
function hasCycle(graph, node, visited, parent) {
  visited.add(node);
  for (let neighbor of graph[node]) {
    if (!visited.has(neighbor)) {
      if (hasCycle(graph, neighbor, visited, node)) return true;
    } else if (neighbor !== parent) {
      return true;
    }
  }
  return false;
}
```

A connected component is a subgraph in which all nodes are reachable from each other.
To count components:
- Use DFS or BFS from every unvisited node.
- Each traversal represents one component.

```js
function countComponents(graph) {
  let visited = new Set();
  let count = 0;
  for (let node in graph) {
    if (!visited.has(node)) {
      dfsRecursive(graph, node, visited);
      count++;
    }
  }
  return count;
}
```

